from reportlab.lib import colors
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from reportlab.lib.colors import HexColor
out=r'output/pdf/AITS-Helpdesk-Quick-Guide.pdf'
navy=HexColor('#16324F'); teal=HexColor('#187C80'); pale=HexColor('#EAF3F5'); ink=HexColor('#253443'); muted=HexColor('#607080')
doc=SimpleDocTemplate(out,pagesize=letter,rightMargin=.7*inch,leftMargin=.7*inch,topMargin=.65*inch,bottomMargin=.65*inch,title='AITS Helpdesk - New User Guide')
s=getSampleStyleSheet(); s.add(ParagraphStyle(name='titlex',parent=s['Title'],fontName='Helvetica-Bold',fontSize=25,leading=30,textColor=navy,spaceAfter=6)); s.add(ParagraphStyle(name='subtitlex',parent=s['Normal'],fontSize=11,leading=15,textColor=muted,spaceAfter=16)); s.add(ParagraphStyle(name='h1x',parent=s['Heading1'],fontSize=17,leading=21,textColor=navy,spaceBefore=8,spaceAfter=9)); s.add(ParagraphStyle(name='h2x',parent=s['Heading2'],fontSize=12,leading=15,textColor=teal,spaceBefore=8,spaceAfter=4)); s.add(ParagraphStyle(name='bodyx',parent=s['BodyText'],fontSize=10,leading=14,textColor=ink,spaceAfter=6)); s.add(ParagraphStyle(name='smallx',parent=s['BodyText'],fontSize=8.7,leading=12,textColor=muted)); s.add(ParagraphStyle(name='callx',parent=s['BodyText'],fontSize=10,leading=14,textColor=navy))
def P(t,st='bodyx'):return Paragraph(t,s[st])
def bullet(t):return P('&bull;&nbsp; '+t)
def box(content):
 t=Table([[content]],colWidths=[7.0*inch]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),pale),('BOX',(0,0),(-1,-1),.5,HexColor('#C9DDE1')),('LEFTPADDING',(0,0),(-1,-1),11),('RIGHTPADDING',(0,0),(-1,-1),11),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)]));return t
story=[P('AITS Helpdesk','titlex'),P('A simple guide for people who are new to the project','subtitlex'),box([P('<b>What is your work here?</b>','callx'),P('Use the helpdesk to report a problem, keep its details and updates together, and help the support team resolve it. What you can see and do depends on your account role.','bodyx')]),P('Who does what?','h1x')]
rows=[[P('<b>Role</b>','bodyx'),P('<b>Your main work</b>','bodyx')],[P('Client user','bodyx'),P('Report problems for your company. Check your tickets, read replies, and add information when asked.','bodyx')],[P('AITS staff','bodyx'),P('Review tickets in your assigned projects. Take ownership, work on the issue, communicate progress, and resolve or escalate it.','bodyx')],[P('Administrator','bodyx'),P('Manage the service: companies, users, projects, support teams, accounts, settings, and tickets. Help users get access.','bodyx')]]
t=Table(rows,colWidths=[1.25*inch,5.75*inch]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),pale),('GRID',(0,0),(-1,-1),.4,HexColor('#CBD5DC')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),3)]));story.append(t)
story += [P('The ticket process','h1x')]
for i,(h,b) in enumerate([('1. Report','Client describes the issue, selects the right project, and submits a ticket. A clear subject and useful details help the team understand it.'),('2. Review','AITS staff read the ticket and any comments. Staff can see tickets for projects they are assigned to.'),('3. Take ownership','A staff member claims an unowned ticket to show they are responsible for moving it forward.'),('4. Work and update','The owner starts work, adds comments or updates, and escalates to a higher support level when needed. Escalation requires a reason.'),('5. Resolve and follow','The owner marks the work resolved. The client can open the ticket to see its status and updates.')],1):
 story += [P(h,'h2x'),P(b)]
story += [PageBreak(),P('Using the helpdesk','h1x'),P('If you are a client','h2x')]
for i,b in enumerate(['Sign in with your client account. If you do not have one, register and select your company.','Choose to create a ticket. Select the project if asked.','Write what is wrong, when it started, and what you were trying to do. Include steps or a photo if they help.','Submit the ticket. Open it later to read progress and reply in the comments.'],1):story.append(P(f'<b>{i}.</b> {b}'))
story += [P('If you are AITS staff','h2x')]
for i,b in enumerate(['Sign in with your AITS account and open your assigned projects or ticket list.','Open a ticket and read the description and existing comments.','Claim the ticket when you are ready to take responsibility. Start work and keep the ticket updated with comments.','Resolve the issue when complete, or escalate it with a reason if another support level needs to take over.'],1):story.append(P(f'<b>{i}.</b> {b}'))
story += [P('If you are an administrator','h2x')]
for b in ['Set up companies and their client users.','Add AITS staff, enable accounts, and approve staff registrations when needed.','Create company projects and assign support team members to L1, L2, or L3. Team membership gives staff access to that project.','Use account and ticket management pages to support the team and keep the service organized.']:story.append(bullet(b))
story += [box([P('<b>Remember</b>','callx'),P('If you cannot find a ticket, it may belong to another company or project, or your role may not have access. Ask an administrator to check your account and project assignment. Never put passwords in ticket comments.','bodyx')]),P('Ticket priority and time','h2x'),P('Priority sets the normal resolution target: Low 72 hours, Medium 24 hours, High 8 hours, Urgent 4 hours. An administrator may change these targets. The ticket shows its deadline and whether it is overdue.','bodyx')]
def footer(c,d):
 c.saveState();w,h=letter;c.setStrokeColor(HexColor('#D8E1E6'));c.line(.7*inch,.48*inch,w-.7*inch,.48*inch);c.setFont('Helvetica',8);c.setFillColor(muted);c.drawString(.7*inch,.31*inch,'AITS Helpdesk | New user guide');c.drawRightString(w-.7*inch,.31*inch,f'Page {d.page}');c.restoreState()
doc.build(story,onFirstPage=footer,onLaterPages=footer);print(out)
